import{_ as e,c as i,o as l,ah as t}from"./chunks/framework.l36K22_3.js";const c="/assets/1691459118.DPEvZ2yt.jpg",o="/assets/1691459749.D7s05ZFg.jpg",_=JSON.parse('{"title":"LICEcap 实用的 GIF 录屏工具","description":"","frontmatter":{},"headers":[],"relativePath":"common-tools/terminal/licecap.md","filePath":"common-tools/terminal/licecap.md","lastUpdated":1788862675000}'),r={name:"common-tools/terminal/licecap.md"};function p(s,a,n,h,d,m){return l(),i("div",null,a[0]||(a[0]=[t('<h1 id="licecap-实用的-gif-录屏工具" tabindex="-1">LICEcap 实用的 GIF 录屏工具 <a class="header-anchor" href="#licecap-实用的-gif-录屏工具" aria-label="Permalink to &quot;LICEcap 实用的 GIF 录屏工具&quot;">​</a></h1><h2 id="licecap" tabindex="-1">LICEcap <a class="header-anchor" href="#licecap" aria-label="Permalink to &quot;LICEcap&quot;">​</a></h2><p>LICEcap 是一款屏幕录制工具，支持导出 GIF 动画图片格式，轻量级、使用简单，录制过程中可以随意改变录屏范围。</p><p>官网 <a href="https://www.cockos.com/licecap/" target="_blank" rel="noreferrer">https://www.cockos.com/licecap/</a></p><p>LICEcap 可以捕获桌面区域并将其直接保存为 .GIF（用于在网络浏览器等中查看）或 .LCF（见下文）。</p><p>LICEcap 是一个直观但灵活的应用程序（适用于 Windows 和现在的 OSX），其设计轻量且具有高性能。</p><p>LICEcap 是 GPL 自由软件，每个下载包都包含源代码。</p><h2 id="特点和选项" tabindex="-1">特点和选项 <a class="header-anchor" href="#特点和选项" aria-label="Permalink to &quot;特点和选项&quot;">​</a></h2><ul><li>直接录制为 .GIF 或 .LCF。</li><li>录制时移动屏幕截图框。</li><li>暂停和重新开始录制，并可选择插入文本消息。</li><li>全局热键（Shift+空格）可在录制时切换暂停</li><li>可调节最大录制帧速率，以允许限制 CPU 使用。</li><li>基本标题框架，带或不带文本。</li><li>记录鼠标按钮的按下情况。</li><li>显示录音中经过的时间。</li></ul><h2 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to &quot;要求&quot;">​</a></h2><ul><li>Windows：Windows XP/Vista/7/8/8.1/10/11（可能会在旧版本上减少功能）</li><li>OSX：macOS 10.7-12.x Intel 64 位或 M1（旧版本：v1.30 支持 macOS 10.6，v1.28 支持 macOS 10.4 和 PPC）</li><li>Linux：显然可以与 WINE 配合使用</li><li>相当快的 CPU</li><li>充足的 RAM（1GB+，尤其是编码为 LCF 时）</li></ul><h2 id="源代码" tabindex="-1">源代码 <a class="header-anchor" href="#源代码" aria-label="Permalink to &quot;源代码&quot;">​</a></h2><p>git 克隆 <a href="https://www-dev.cockos.com/licecap/licecap.git" target="_blank" rel="noreferrer">https://www-dev.cockos.com/licecap/licecap.git</a> 官方 GitHub 镜像：<a href="https://www.github.com/justinfrankel/licecap.git" target="_blank" rel="noreferrer">github.com/justinfrankel/licecap</a></p><h2 id="操作说明" tabindex="-1">操作说明 <a class="header-anchor" href="#操作说明" aria-label="Permalink to &quot;操作说明&quot;">​</a></h2><p>一、打开 LICEcap，会见到如下页面，拖动页面边缘即可调整录屏框大小</p><p><img src="'+c+'" alt="" loading="lazy"></p><p>二、进入属性设置页面，设置属性后开始录制</p><p><img src="'+o+'" alt="" loading="lazy"></p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h2><p>打开官网链接，下滑至官网底部，可下载不同系统的最新版</p>',20)]))}const f=e(r,[["render",p]]);export{_ as __pageData,f as default};
